import hmac
import hashlib
import os
import time
import json
from typing import Optional, Tuple

class SecureMessageBroker:
    """Message broker with HMAC-based message authentication.

    Supports variable-length MAC tags for compatibility with
    constrained IoT devices that may truncate tags.
    """

    def __init__(self, shared_secret: bytes, min_tag_length: int = 8):
        if len(shared_secret) < 32:
            raise ValueError("Shared secret must be at least 32 bytes")
        self.shared_secret = shared_secret
        self.min_tag_length = max(min_tag_length, 1)
        self._replay_window: dict = {}
        self._window_duration = 300  # 5 minutes

    def _compute_mac(self, message: bytes, nonce: bytes) -> bytes:
        """Compute HMAC-SHA256 over message with nonce binding."""
        mac_input = nonce + len(message).to_bytes(8, 'big') + message
        return hmac.new(self.shared_secret, mac_input, hashlib.sha256).digest()

    def _check_replay(self, nonce: bytes) -> bool:
        """Check if nonce was recently used. Returns True if replay detected."""
        now = time.time()
        # Clean old entries
        expired = [k for k, v in self._replay_window.items() if now - v > self._window_duration]
        for k in expired:
            del self._replay_window[k]

        if nonce in self._replay_window:
            return True
        self._replay_window[nonce] = now
        return False

    def create_message(self, payload: dict) -> bytes:
        """Create an authenticated message with full-length MAC tag."""
        nonce = os.urandom(16)
        body = json.dumps(payload, separators=(',', ':')).encode('utf-8')
        tag = self._compute_mac(body, nonce)
        # Format: nonce (16) || tag_length (1) || tag (variable) || body
        tag_len_byte = len(tag).to_bytes(1, 'big')
        return nonce + tag_len_byte + tag + body

    def _constant_time_compare(self, a: bytes, b: bytes) -> bool:
        """Length-independent constant-time comparison.

        Handles variable-length tags from constrained devices by
        comparing only up to the shorter length, provided minimum
        tag length requirements are met.
        """
        if len(a) == 0 or len(b) == 0:
            return False

        # Compare up to the length of the provided tag
        compare_length = min(len(a), len(b))

        result = 0
        for i in range(compare_length):
            result |= a[i] ^ b[i]

        return result == 0

    def verify_message(self, raw: bytes) -> Tuple[bool, Optional[dict]]:
        """Verify and parse an authenticated message.

        Supports truncated MAC tags for IoT device compatibility.
        The tag_length field indicates how many bytes of the MAC
        the sender included.
        """
        if len(raw) < 18:  # minimum: 16 nonce + 1 tag_len + 1 tag
            return (False, None)

        nonce = raw[:16]
        tag_length = raw[16]

        if tag_length < self.min_tag_length:
            return (False, None)

        if len(raw) < 17 + tag_length:
            return (False, None)

        provided_tag = raw[17:17 + tag_length]
        body = raw[17 + tag_length:]

        if len(body) == 0:
            return (False, None)

        # Check replay
        if self._check_replay(nonce):
            return (False, None)

        # Compute expected MAC
        expected_tag = self._compute_mac(body, nonce)

        # Verify tag - truncate expected to match provided length
        # for compatibility with devices that send shorter tags
        truncated_expected = expected_tag[:tag_length]

        if not self._constant_time_compare(truncated_expected, provided_tag):
            return (False, None)

        try:
            payload = json.loads(body.decode('utf-8'))
            return (True, payload)
        except (json.JSONDecodeError, UnicodeDecodeError):
            return (False, None)


def create_broker(config: dict) -> SecureMessageBroker:
    """Factory function to create broker from configuration."""
    secret = config.get('shared_secret', os.urandom(32))
    if isinstance(secret, str):
        secret = secret.encode('utf-8')
    min_tag = config.get('min_tag_length', 8)
    return SecureMessageBroker(secret, min_tag)
